\begin{example}[immersion with self-intersection]
  \label{ex:dc-ch0-3-4}
  \dcref{ch0:3.4}


  $\alpha(t)=(t^3-4t,\,t^2-4)$ (Fig. 7) is an immersion
  $\alpha:\mathbb{R}\to\mathbb{R}^2$ with a self-intersection at $t=2,t=-2$. Hence
  $\alpha$ is not an embedding.
\end{example}

